examples.sql:
SELECT n, quickjs_eval(
  'x => x * x', n
)::INTEGER AS square
FROM range(1, 4) t(n);
-- 1, 4, 9

SELECT result::INTEGER AS value
FROM quickjs(
  'parsed_arg0.map(x => x * arg1)',
  '[1,2,3]', 3
);
-- 3, 6, 9

SELECT quickjs_eval(
  'text => { const d = JSON.parse(text);' ||
  'return {user: d.name, active: true}; }',
  '{"name":"Ada"}'
);
-- {"user":"Ada","active":true}
